<?php
declare(strict_types=1);
require __DIR__."/../conexion.php";
require __DIR__."/../producto_servicio.php";

$base=rtrim($argv[1]??"http://127.0.0.1:8102","/");$db=Conexion::obtenerInstancia();$marca="EANLOT".bin2hex(random_bytes(3));$usuarios=[];$productos=[];$ventas=[];
function ok2(bool $c,string $m):void{if(!$c)throw new RuntimeException("FALLÓ: {$m}");echo"OK: {$m}\n";}
function req2(string $base,string $ruta,string $sid,array $post=[],array $headers=[]):array{$c=curl_init($base."/".ltrim($ruta,"/"));curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true,CURLOPT_COOKIE=>"PHPSESSID={$sid}",CURLOPT_HTTPHEADER=>$headers,CURLOPT_TIMEOUT=>10]);if($post!==[]){curl_setopt($c,CURLOPT_POST,true);curl_setopt($c,CURLOPT_POSTFIELDS,http_build_query($post));}$r=curl_exec($c);if($r===false)throw new RuntimeException(curl_error($c));$hs=curl_getinfo($c,CURLINFO_HEADER_SIZE);return["status"=>curl_getinfo($c,CURLINFO_RESPONSE_CODE),"body"=>substr($r,$hs)];}
function ses2(array $u,string $csrf):string{$sid=bin2hex(random_bytes(16));session_id($sid);session_start();$_SESSION=["usuario_id"=>(int)$u["id"],"usuario_dni"=>$u["dni"],"usuario_nombre"=>$u["nombre"],"usuario_apellido"=>$u["apellido"],"usuario_rol"=>$u["rol"],"mfa_verified"=>true,"csrf_token"=>$csrf];session_write_close();return$sid;}
function j2(array $r):array{return json_decode($r["body"],true,512,JSON_THROW_ON_ERROR);}

try{
 foreach(["admin","vendedor","cliente"]as$i=>$rol){$dni=$marca.($i+1);$hash=password_hash("Temporal1!",PASSWORD_DEFAULT);$s=$db->prepare("INSERT INTO usuarios(dni,nombre,apellido,password,rol)VALUES(?,?, 'Prueba',?,?)");$s->execute([$dni,$rol,$hash,$rol]);$usuarios[$rol]=["id"=>$db->insert_id,"dni"=>$dni,"nombre"=>$rol,"apellido"=>"Prueba","rol"=>$rol];}
 $csrf=bin2hex(random_bytes(32));foreach($usuarios as$k=>$u)$usuarios[$k]["sid"]=ses2($u,$csrf);$h=["X-CSRF-Token: {$csrf}"];$categoria=(int)$db->query("SELECT id FROM categorias WHERE activo=1 ORDER BY id LIMIT 1")->fetch_assoc()["id"];
 ok2(ean13Valido("7791234567898")&&!ean13Valido("7791234567890"),"checksum EAN-13 distingue código válido e inválido");
 $baseProducto=["nombre"=>$marca." Alfajor","marca"=>"Marca Prueba","descripcion"=>"Descripción <segura>","precio"=>"18000","stock"=>"4","stock_minimo"=>"5","unidad_venta_codigo"=>"CAJA","unidades_por_presentacion"=>"24","unidad_base_codigo"=>"UNIDAD","categoria_id"=>(string)$categoria,"numero_lote"=>"FUT15","fecha_ingreso"=>date("Y-m-d"),"fecha_vencimiento"=>date("Y-m-d",strtotime("+15 days"))];
 foreach(["123456789012","12345678901288","ABC4567890128","7791234567890"]as$invalido){$r=req2($base,"guardar_producto.php",$usuarios["admin"]["sid"],[...$baseProducto,"ean13"=>$invalido],$h);ok2($r["status"]===400,"rechaza EAN-13 inválido: {$invalido}");}
 $crear=req2($base,"guardar_producto.php",$usuarios["admin"]["sid"],[...$baseProducto,"ean13"=>"7791234567898"],$h);ok2($crear["status"]===201,"crea producto con EAN-13 válido");$productos[]=(int)j2($crear)["producto_id"];$pid=$productos[0];
 $duplicado=req2($base,"guardar_producto.php",$usuarios["admin"]["sid"],[...$baseProducto,"nombre"=>$marca." Duplicado","ean13"=>"7791234567898"],$h);ok2($duplicado["status"]===409&&str_contains(j2($duplicado)["error"],"Ya existe"),"restricción única informa EAN-13 duplicado");
 $fila=$db->query("SELECT fecha_alta,stock,stock_minimo,unidades_por_presentacion FROM productos WHERE id={$pid}")->fetch_assoc();ok2($fila["fecha_alta"]!==null&&(int)$fila["stock"]===4&&(int)$fila["stock_minimo"]===5&&(int)$fila["unidades_por_presentacion"]===24,"fecha de alta, stock mínimo y equivalencia persisten");
 $scan=req2($base,"buscar_producto_ean.php?ean13=7791234567898",$usuarios["vendedor"]["sid"]);ok2($scan["status"]===200&&(int)j2($scan)["id"]===$pid,"vendedor localiza producto mediante scanner EAN-13");
 $f1=j2(req2($base,"obtener_productos.php?marca=Marca%20Prueba&stock_estado=bajo&precio_min=17000&precio_max=19000",$usuarios["admin"]["sid"]));ok2(count($f1)===1&&(int)$f1[0]["id"]===$pid,"filtros backend combinan marca, stock bajo y precio");
 $f2=j2(req2($base,"obtener_productos.php?ean13=7791234567898&vencimiento=proximo",$usuarios["admin"]["sid"]));ok2(count($f2)===1,"filtros backend combinan EAN-13 y vencimiento próximo");
 $alertas=j2(req2($base,"obtener_alertas_inventario.php",$usuarios["admin"]["sid"]));ok2((bool)array_filter($alertas["stock_bajo"],fn($x)=>(int)$x["id"]===$pid)&&(bool)array_filter($alertas["proximos"],fn($x)=>(int)$x["producto_id"]===$pid),"centro de alertas muestra stock bajo y lote próximo");
 $ing=req2($base,"ingresar_stock.php",$usuarios["admin"]["sid"],["producto_id"=>(string)$pid,"cantidad"=>"2","numero_lote"=>"VENCIDO","fecha_ingreso"=>date("Y-m-d",strtotime("-40 days")),"fecha_vencimiento"=>date("Y-m-d",strtotime("-1 day")),"motivo"=>"Prueba vencido"],$h);ok2($ing["status"]===201,"registra lote vencido con trazabilidad");
 $disp=j2(req2($base,"buscar_producto_ean.php?ean13=7791234567898",$usuarios["vendedor"]["sid"]));ok2((int)$disp["stock"]===6&&(int)$disp["stock_vendible"]===4,"stock físico incluye vencido pero stock vendible lo excluye");
 $venta=req2($base,"guardar_venta.php",$usuarios["vendedor"]["sid"],["producto_id"=>(string)$pid,"cliente_id"=>(string)$usuarios["cliente"]["id"],"cantidad"=>"4","porcentaje_vendedor"=>"0"],$h);ok2($venta["status"]===201,"venta descuenta lote vigente mediante FEFO");$ventas[]=(int)j2($venta)["venta_id"];$vid=$ventas[0];
 $usado=$db->query("SELECT l.numero_lote,vl.cantidad FROM venta_lotes vl JOIN producto_lotes l ON l.id=vl.lote_id WHERE vl.venta_id={$vid}")->fetch_assoc();ok2($usado["numero_lote"]==="FUT15"&&(int)$usado["cantidad"]===4,"FEFO no utiliza el lote vencido");
 $sinVigente=req2($base,"guardar_venta.php",$usuarios["vendedor"]["sid"],["producto_id"=>(string)$pid,"cliente_id"=>(string)$usuarios["cliente"]["id"],"cantidad"=>"1","porcentaje_vendedor"=>"0"],$h);ok2($sinVigente["status"]===400,"impide vender cuando solo queda stock vencido");
 $detalle=j2(req2($base,"obtener_detalle_producto.php?id={$pid}",$usuarios["admin"]["sid"]));ok2((int)$detalle["metricas"]["presentaciones_vendidas"]===4&&(int)$detalle["metricas"]["unidades_equivalentes"]===96&&(int)$detalle["metricas"]["operaciones"]===1,"reporte calcula 4 cajas = 96 unidades y una operación");
 $cancelar=req2($base,"modificar_venta.php",$usuarios["vendedor"]["sid"],["venta_id"=>(string)$vid,"accion"=>"cancelar","motivo"=>"Prueba FEFO"],$h);ok2($cancelar["status"]===200,"cancelación devuelve el stock al lote original");$restaurado=$db->query("SELECT stock_actual FROM producto_lotes WHERE producto_id={$pid} AND numero_lote='FUT15'")->fetch_assoc();ok2((int)$restaurado["stock_actual"]===4,"lote vigente queda restaurado exactamente");
 $baja=req2($base,"eliminar_producto.php",$usuarios["admin"]["sid"],["id"=>(string)$pid],$h);ok2($baja["status"]===200,"baja lógica conserva el producto");$ciclo=$db->query("SELECT activo,fecha_alta,fecha_baja FROM productos WHERE id={$pid}")->fetch_assoc();ok2((int)$ciclo["activo"]===0&&$ciclo["fecha_baja"]!==null&&$ciclo["fecha_baja"]>=$ciclo["fecha_alta"],"fecha de baja es válida y posterior al alta");
 $oculto=j2(req2($base,"obtener_productos.php?ean13=7791234567898",$usuarios["vendedor"]["sid"]));ok2(count($oculto)===0,"producto inactivo no aparece en nuevas ventas");
}finally{
 if($ventas){$ids=implode(",",array_map("intval",$ventas));$db->query("DELETE FROM stock_movimientos WHERE venta_id IN({$ids})");$db->query("DELETE FROM venta_historial WHERE venta_id IN({$ids})");$db->query("DELETE FROM venta_lotes WHERE venta_id IN({$ids})");$db->query("DELETE FROM ventas WHERE id IN({$ids})");}
 if($productos){$ids=implode(",",array_map("intval",$productos));$db->query("DELETE FROM stock_movimientos WHERE producto_id IN({$ids})");$db->query("DELETE FROM producto_historial WHERE producto_id IN({$ids})");$db->query("DELETE FROM producto_lotes WHERE producto_id IN({$ids})");$db->query("DELETE FROM productos WHERE id IN({$ids})");}
 if($usuarios){$ids=implode(",",array_map(fn($u)=>(int)$u["id"],$usuarios));$db->query("DELETE FROM usuarios WHERE id IN({$ids}) AND dni LIKE 'EANLOT%'");}
}
echo"Integración EAN-13, lotes y reportes completada correctamente.\n";
